TYPE.TEST:


SetFunctionName("GetSoa4MaskScalar_True()");
Soa4MaskScalar m = GetSoa4MaskScalar_True();
Validate( IsEqual(m, CreateSoa4MaskScalar(true, true, true, true)) );



SetFunctionName("GetSoa4MaskScalar_False()");
Soa4MaskScalar m = GetSoa4MaskScalar_False();
Validate( IsEqual(m, CreateSoa4MaskScalar(false, false, false, false)) );



SetFunctionName("GetSoa4Float_NegativeTwo()");
Soa4Float v1 = GetSoa4Float_NegativeTwo();
Validate( IsEqual( v1, Soa4FloatFromFloat(-2.0f) ) );



SetFunctionName("GetSoa4Float_NegativeOne()");
Soa4Float v1 = GetSoa4Float_NegativeOne();
Validate( IsEqual( v1, Soa4FloatFromFloat(-1.0f) ) );



SetFunctionName("GetSoa4Float_NegativeHalf()");
Soa4Float v1 = GetSoa4Float_NegativeHalf();
Validate( IsEqual( v1, Soa4FloatFromFloat(-0.5f) ) );



SetFunctionName("GetSoa4Float_NegativeZero()");
Soa4Float v1 = GetSoa4Float_NegativeZero();
Validate( IsEqual( v1, Soa4FloatFromFloat(-0.0f) ) );



SetFunctionName("GetSoa4Float_Zero()");
Soa4Float v1 = GetSoa4Float_Zero();
Validate( IsEqual( v1, Soa4FloatFromFloat(0.0f) ) );



SetFunctionName("GetSoa4Float_Half()");
Soa4Float v1 = GetSoa4Float_Half();
Validate( IsEqual( v1, Soa4FloatFromFloat(0.5f) ) );



SetFunctionName("GetSoa4Float_One()");
Soa4Float v1 = GetSoa4Float_One();
Validate( IsEqual( v1, Soa4FloatFromFloat(1.0f) ) );



SetFunctionName("GetSoa4Float_Two()");
Soa4Float v1 = GetSoa4Float_Two();
Validate( IsEqual( v1, Soa4FloatFromFloat(2.0f) ) );
